// public/map/obrys.ts
var EPS = 0.000000001;
var MITER_LIMIT = 8;
function getPolygons(geometry) {
  if (!geometry) {
    return [];
  }
  if (geometry.type === "Polygon") {
    return [geometry.coordinates];
  }
  if (geometry.type === "MultiPolygon") {
    return geometry.coordinates;
  }
  return [];
}
function toPoint([lon, lat], kx, ky) {
  return { x: lon * kx, y: lat * ky };
}
function toPosition({ x, y }, kx, ky) {
  return [x / kx, y / ky];
}
function signedArea(ring) {
  let sum = 0;
  for (let i = 0, j = ring.length - 1;i < ring.length; j = i++) {
    sum += ring[j].x * ring[i].y - ring[i].x * ring[j].y;
  }
  return sum / 2;
}
function getOffsetLines(ring, distance, hole) {
  const lines = [];
  const area = signedArea(ring);
  if (Math.abs(area) < EPS) {
    return null;
  }
  let side = area > 0 ? 1 : -1;
  if (hole) {
    side = -side;
  }
  for (let i = 0;i < ring.length; i++) {
    const from = ring[i];
    const to = ring[(i + 1) % ring.length];
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const length = Math.hypot(dx, dy);
    if (length < EPS) {
      return null;
    }
    const tx = dx / length;
    const ty = dy / length;
    const nx = -ty * side;
    const ny = tx * side;
    lines.push({
      point: { x: from.x + nx * distance, y: from.y + ny * distance },
      dir: { x: tx, y: ty }
    });
  }
  return lines;
}
function intersectLines(first, second) {
  const cross = first.dir.x * second.dir.y - first.dir.y * second.dir.x;
  if (Math.abs(cross) < 0.000001) {
    return null;
  }
  const dx = second.point.x - first.point.x;
  const dy = second.point.y - first.point.y;
  const t = (dx * second.dir.y - dy * second.dir.x) / cross;
  return {
    x: first.point.x + first.dir.x * t,
    y: first.point.y + first.dir.y * t
  };
}
function offsetRing(ring, distance, hole) {
  const area = signedArea(ring);
  if (Math.abs(area) < EPS) {
    return null;
  }
  const lines = getOffsetLines(ring, distance, hole);
  if (!lines) {
    return null;
  }
  const result = [];
  for (let i = 0;i < lines.length; i++) {
    const previous = lines[(i - 1 + lines.length) % lines.length];
    const current = lines[i];
    const point = intersectLines(previous, current) ?? { ...current.point };
    if (Math.hypot(point.x - ring[i].x, point.y - ring[i].y) > distance * MITER_LIMIT) {
      return null;
    }
    result.push(point);
  }
  const newArea = signedArea(result);
  if (Math.abs(newArea) < EPS || Math.sign(newArea) !== Math.sign(area)) {
    return null;
  }
  for (let i = 0;i < result.length; i++) {
    const from = result[i];
    const to = result[(i + 1) % result.length];
    const originalFrom = ring[i];
    const originalTo = ring[(i + 1) % ring.length];
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    if (Math.hypot(dx, dy) < EPS) {
      return null;
    }
    const originalDx = originalTo.x - originalFrom.x;
    const originalDy = originalTo.y - originalFrom.y;
    if (dx * originalDx + dy * originalDy <= 0) {
      return null;
    }
  }
  return result;
}
function getObrysWewnetrzny(geometry, distance) {
  const result = [];
  for (const rings of getPolygons(geometry)) {
    if (rings.length === 0) {
      continue;
    }
    const latSum = rings[0].reduce((sum, point) => sum + point[1], 0);
    const lat0 = latSum / rings[0].length;
    const kx = 111320 * Math.cos(lat0 * Math.PI / 180);
    const ky = 110540;
    for (let i = 0;i < rings.length; i++) {
      const projected = rings[i].map((point) => toPoint(point, kx, ky));
      if (projected.length > 1) {
        const first = projected[0];
        const last = projected[projected.length - 1];
        if (first.x === last.x && first.y === last.y) {
          projected.pop();
        }
      }
      if (projected.length < 3) {
        continue;
      }
      const offset = offsetRing(projected, distance, i > 0);
      if (offset) {
        result.push([...offset.map((point) => toPosition(point, kx, ky)), toPosition(offset[0], kx, ky)]);
      }
    }
  }
  return result;
}

// public/map/schody.ts
var STEP_SPACING = 0.5;
var MAX_STEPS = 30;
var EPS2 = 0.000000001;
function getPolygons2(geometry) {
  if (!geometry) {
    return [];
  }
  if (geometry.type === "Polygon") {
    return [geometry.coordinates];
  }
  if (geometry.type === "MultiPolygon") {
    return geometry.coordinates;
  }
  return [];
}
function getDirectionLine(geometry) {
  if (!geometry) {
    return null;
  }
  if (geometry.type === "LineString") {
    return geometry.coordinates;
  }
  if (geometry.type === "MultiLineString") {
    return geometry.coordinates[0] ?? null;
  }
  return null;
}
function toPoint2([lon, lat], kx, ky) {
  return { x: lon * kx, y: lat * ky };
}
function toPosition2({ x, y }, kx, ky) {
  return [x / kx, y / ky];
}
function dot(a, b) {
  return a.x * b.x + a.y * b.y;
}
function getStepsForPolygon(rings, direction) {
  if (rings.length === 0 || rings[0].length < 3 || direction.length < 2) {
    return [];
  }
  const latSum = rings[0].reduce((sum, point) => sum + point[1], 0);
  const lat0 = latSum / rings[0].length;
  const kx = 111320 * Math.cos(lat0 * Math.PI / 180);
  const ky = 110540;
  const projectedRings = rings.map((ring) => ring.map((point) => toPoint2(point, kx, ky)));
  const start = toPoint2(direction[0], kx, ky);
  const end = toPoint2(direction[direction.length - 1], kx, ky);
  const dirLength = Math.hypot(end.x - start.x, end.y - start.y);
  if (dirLength < EPS2) {
    return [];
  }
  const dir = {
    x: (end.x - start.x) / dirLength,
    y: (end.y - start.y) / dirLength
  };
  const normal = { x: -dir.y, y: dir.x };
  let minU = Infinity;
  let maxU = -Infinity;
  for (const ring of projectedRings) {
    for (const point of ring) {
      const u = dot(point, dir);
      if (u < minU) {
        minU = u;
      }
      if (u > maxU) {
        maxU = u;
      }
    }
  }
  const runLength = maxU - minU;
  if (runLength < EPS2) {
    return [];
  }
  const stepCount = Math.max(1, Math.min(MAX_STEPS, Math.floor(runLength / STEP_SPACING)));
  const result = [];
  for (let i = 1;i <= stepCount; i++) {
    const u = minU + runLength * i / (stepCount + 1);
    const base = { x: dir.x * u, y: dir.y * u };
    const params = [];
    for (const ring of projectedRings) {
      for (let j = 0, k = ring.length - 1;j < ring.length; k = j++) {
        const a = ring[k];
        const b = ring[j];
        const da = dot(a, dir) - u;
        const db = dot(b, dir) - u;
        if (da > EPS2 && db > EPS2 || da < -EPS2 && db < -EPS2) {
          continue;
        }
        if (Math.abs(da - db) <= EPS2) {
          continue;
        }
        const t = da / (da - db);
        if (t < -EPS2 || t > 1 + EPS2) {
          continue;
        }
        const x = a.x + (b.x - a.x) * t;
        const y = a.y + (b.y - a.y) * t;
        params.push((x - base.x) * normal.x + (y - base.y) * normal.y);
      }
    }
    if (params.length < 2) {
      continue;
    }
    params.sort((a, b) => a - b);
    const unique = [];
    for (const param of params) {
      if (unique.length === 0 || Math.abs(param - unique[unique.length - 1]) > 0.000001) {
        unique.push(param);
      }
    }
    for (let j = 0;j + 1 < unique.length; j += 2) {
      const from = {
        x: base.x + normal.x * unique[j],
        y: base.y + normal.y * unique[j]
      };
      const to = {
        x: base.x + normal.x * unique[j + 1],
        y: base.y + normal.y * unique[j + 1]
      };
      if (Math.hypot(to.x - from.x, to.y - from.y) > 0.01) {
        result.push([toPosition2(from, kx, ky), toPosition2(to, kx, ky)]);
      }
    }
  }
  return result;
}
function getSchodySteps(polygon, direction) {
  const directionLine = getDirectionLine(direction);
  if (!directionLine) {
    return [];
  }
  const result = [];
  for (const rings of getPolygons2(polygon)) {
    result.push(...getStepsForPolygon(rings, directionLine));
  }
  return result;
}

// public/map/wzory.ts
function getPolygons3(geometry) {
  if (!geometry) {
    return [];
  }
  if (geometry.type === "Polygon") {
    return [geometry.coordinates];
  }
  if (geometry.type === "MultiPolygon") {
    return geometry.coordinates;
  }
  return [];
}
function ringContains(point, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1;i < ring.length; j = i++) {
    const a = ring[i];
    const b = ring[j];
    if (a.y > point.y !== b.y > point.y && point.x < (b.x - a.x) * (point.y - a.y) / (b.y - a.y) + a.x) {
      inside = !inside;
    }
  }
  return inside;
}
function polygonContains(point, rings) {
  if (rings.length === 0 || !ringContains(point, rings[0])) {
    return false;
  }
  for (let i = 1;i < rings.length; i++) {
    if (ringContains(point, rings[i])) {
      return false;
    }
  }
  return true;
}
function getKropkiWzoru(geometry, toScreen, toPosition, stepX, stepY) {
  const polygons = getPolygons3(geometry);
  const result = [];
  if (polygons.length === 0) {
    return result;
  }
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  const screenPolygons = polygons.map((rings) => rings.map((ring) => ring.map((position) => {
    const point = toScreen(position);
    minX = Math.min(minX, point.x);
    minY = Math.min(minY, point.y);
    maxX = Math.max(maxX, point.x);
    maxY = Math.max(maxY, point.y);
    return point;
  })));
  if (!Number.isFinite(minX) || !Number.isFinite(minY)) {
    return result;
  }
  const colStep = Math.max(1, stepX);
  const rowStep = Math.max(1, stepY);
  const firstRow = Math.floor(minY / rowStep);
  for (let row = firstRow;row * rowStep <= maxY; row++) {
    const y = row * rowStep;
    const offset = row % 2 === 0 ? 0 : colStep / 2;
    const firstCol = Math.floor((minX - offset) / colStep);
    for (let col = firstCol;col * colStep + offset <= maxX; col++) {
      const point = { x: col * colStep + offset, y };
      if (screenPolygons.some((rings) => polygonContains(point, rings))) {
        result.push(toPosition(point));
      }
    }
  }
  return result;
}

