function getDokument(id) {
  let ret = '<div class="padded bottom-dashed-line">';
  const obj = egbFeatures.dokumenty.get(id);
  if (obj) {
    ret += '<div><span class="item">Utw. obiektu: </span>';
    if (obj.startObiekt) {
      ret += new Date(obj.startObiekt).toLocaleString("pl-PL");
    } else {
      ret += '<span class="error-inline">Brak daty utworzenia obiektu</span>';
    }
    if (obj.koniecObiekt) {
      ret += '<span class="item">&nbspKoniec obiektu: </span>' + new Date(obj.koniecObiekt).toLocaleString("pl-PL");
    }
    ret += "</div>";
    ret += "<div>";
    if (obj.dataDokumentu) {
      ret += '<span class="item">Data dokumentu: </span>';
      ret += new Date(obj.dataDokumentu).toLocaleDateString("pl-PL") + " ";
    }
    ret += '<span class="item">Rodzaj dokumentu: </span>';
    if (obj.rodzajDokumentu) {
      const rodzajDokumentu = EGB_RodzajDokumentu[obj.rodzajDokumentu];
      if (rodzajDokumentu) {
        ret += rodzajDokumentu;
      } else {
        ret += ret += '<span class="error-inline">Nieprawidłowa wartość</span>';
      }
    } else {
      ret += '<span class="error-inline">Brak rodzaju</span>';
    }
    ret += "</div>";
    ret += '<div><span class="item">Tytuł: </span>';
    if (obj.tytul == null) {
      ret += '<span class="error-inline">Brak tytułu</span>';
    } else {
      ret += obj.tytul;
    }
    ret += "</div>";
    ret += '<div><span class="item">Nazwa twórcy dokumentu: </span>';
    if (obj.nazwaTworcyDokumentu == null) {
      ret += '<span class="error-inline">Brak nazwy twórcy</span>';
    } else {
      ret += obj.nazwaTworcyDokumentu;
    }
    ret += "</div>";
    ret += '<div><span class="item">Opis dokumentu: </span>';
    if (obj.opisDokumentu == null) {
      ret += '<span class="error-inline">Brak opisu</span>';
    } else {
      ret += obj.opisDokumentu;
    }
    ret += "</div>";
    ret += '<div><span class="item">Sygnatura dokumentu: </span>';
    if (obj.sygnaturaDokumentu == null) {
      ret += '<span class="error-inline">Brak sygnatury</span>';
    } else {
      ret += obj.sygnaturaDokumentu;
    }
    ret += '<span class="item">&nbspOznaczenie kancelaryjne dokumentu: </span>';
    if (obj.oznKancelaryjneDokumentu == null) {
      ret += '<span class="error-inline">Brak oznaczenia kancelaryjnego</span>';
    } else {
      ret += obj.oznKancelaryjneDokumentu;
    }
    ret += "</div>";
    if (obj.zasobSieciowy) {
      ret += '<div class="item">Zasob sieciowy: </div><div class="div-scroll">';
      if (Array.isArray(obj.zasobSieciowy)) {
        obj.zasobSieciowy.forEach((key) => {
          ret += "<div>" + key.linkage.URL ? key.linkage.URL : "" + "</div>";
        });
      } else {
        ret += "<div>" + obj.zasobSieciowy.linkage.URL ? obj.zasobSieciowy.linkage.URL : "" + "</div>";
      }
      ret += "</div>";
    }
    if (obj.zalacznikDokumentu) {
      ret += '<div class="item">Załącznik dokumentu: </div><div class="div-scroll">';
      ret += getDokumenty(obj.zalacznikDokumentu);
      ret += "</div>";
    }
    ret += '<div><span class="item">IIP: </span>';
    if (obj.idIIP) {
      ret += idIIPtoText(obj.idIIP);
    } else {
      ret += '<span class="error-inline">Brak IIP</span>';
    }
    ret += "</div>";
  } else {
    ret += '<div class="error-inline">Brak dokumentu o podanym gml id</div>';
  }
  ret += "</div>";
  return ret;
}
function pokazDokument(id) {
  const wrapper = document.getElementById("main-wrapper");
  if (wrapper) {
    let html = '<div class="div-title"><span class="item">Dokument: </span></div>';
    html += '<div class="grid-container">' + getDokument(id) + "</div>";
    const div = document.createElement("div");
    div.innerHTML = html;
    wrapper.appendChild(div);
  }
}

// public/egib/obreby-ewidencyjne.ts
function getJE(obj) {
  let ret = "";
  if (obj.lokalizacjaObrebu == null) {
    ret = '<span class="error-inline">&nbspBrak lokalizacji obrębu</span>';
  } else if (obj.lokalizacjaObrebu) {
    ret += '<span class="span-title item">Jednostka ewid.: </span>';
    const objJE = egbFeatures.jednostkiEwidencyjne.get(obj.lokalizacjaObrebu._attributes.href);
    if (objJE) {
      ret += '<span class="cursor-pointer" id="' + "je" /* iJednostkaEwidencyjna */ + objJE._attributes.id + '" onclick="showEgbFeature(this.id)">';
      if (objJE.idJednostkiEwid) {
        ret += objJE.idJednostkiEwid;
      } else {
        ret += '<span class="error-inline">Brak identyfikatora jednostki ewidencyjnej</span>';
      }
      ret += "</span>";
      if (objJE.nazwaWlasna) {
        ret += "<span> (" + objJE.nazwaWlasna + ")</span>";
      }
    } else {
      ret += '<span class="error-inline">Brak jednostki ewidencyjnej o podanym gml id</span>';
    }
  }
  return ret;
}
function getLokalizacja(obj) {
  let ret = '<div class="div-title">';
  ret += '<span class="item">Identyfikator obrębu ewidencyjnego: </span>';
  if (obj.idObrebu) {
    ret += '<span class="bold">' + obj.idObrebu + "</span>";
  } else {
    ret += '<span class="error-inline">Brak identyfikatora obrębu</span>';
  }
  ret += getJE(obj);
  if (obj.idObrebu) {
    ret += '</span><span class="span-title item">Nr obrębu: </span><span>' + obj.idObrebu.split(".").pop() + "</span>";
  }
  ret += "</div>";
  return ret;
}
function getPunktyGraniczne(obj) {
  let ret = '<div><div class="item">Punkty graniczne:</div><div class="div-scroll">';
  if (obj.punktGranicyObrebu == null) {
    ret += '<div class="error-inline">Brak punktów granicznych</div>';
  } else if (obj.punktGranicyObrebu.length < 3) {
    ret += '<div class="error-inline">Za mała liczba punktów granicznych</div>';
  } else {
    obj.punktGranicyObrebu.forEach((key) => {
      if (key) {
        ret += getIdPunktuGranicznego(key._attributes.href);
      }
    });
  }
  ret += "</div></div>";
  return ret;
}
function pokazObrebEwidencyjny(id) {
  const obj = egbFeatures.obrebyEwidencyjne.get(id);
  if (obj) {
    if (obj.geometria) {
      showOnMapButton();
    }
    const wrapper = document.getElementById("main-wrapper");
    if (wrapper) {
      let html = getLokalizacja(obj);
      html += '<div class="grid-container">';
      html += getOgolnyObiekt(obj);
      html += getNazwe(obj);
      html += getPunktyGraniczne(obj);
      html += "</div>";
      let div = document.createElement("div");
      div.innerHTML = html;
      wrapper.appendChild(div);
    }
  }
}

