// public/egib/zmiany.ts
function getZmiana(id) {
  let ret = '<div class="padded bottom-dashed-line">';
  const obj = egbFeatures.zmiany.get(id);
  if (obj) {
    ret += '<div><span class="item">Utw. obiektu: </span>';
    if (obj.startObiekt) {
      ret += new Date(obj.startObiekt).toLocaleString("pl-PL");
    } else {
      ret += '<span class="error-inline">Brak daty utworzenia obiektu</span>';
    }
    if (obj.koniecObiekt) {
      ret += '<span class="item">&nbspKoniec obiektu: </span>' + obj.koniecObiekt;
    }
    ret += "</div>";
    ret += '<div><span class="item">Data przyjęcia zgłoszenia zmiany: </span>';
    if (obj.dataPrzyjeciaZgloszeniaZmiany) {
      ret += new Date(obj.dataPrzyjeciaZgloszeniaZmiany).toLocaleDateString("pl-PL");
    } else {
      ret += '<span class="error-inline">Brak daty przyjęcia zgłoszenia</span>';
    }
    ret += '<span class="item">&nbspData akceptacji zmiany: </span>';
    if (obj.dataAkceptacjiZmiany) {
      ret += new Date(obj.dataAkceptacjiZmiany).toLocaleDateString("pl-PL");
    } else {
      ret += '<span class="error-inline">Brak daty akceptacji</span>';
    }
    ret += "</div>";
    ret += '<div><span class="item">Numer zmiany: </span>';
    if (obj.nrZmiany == null) {
      ret += '<span class="error-inline">Brak numeru</span>';
    } else {
      ret += obj.nrZmiany;
    }
    ret += "</div>";
    ret += '<div><span class="item">Opis zmiany: </span>';
    if (obj.opisZmiany == null) {
      ret += '<span class="error-inline">Brak opisu</span>';
    } else {
      ret += obj.opisZmiany;
    }
    ret += "</div>";
    if (obj.dokument1) {
      ret += '<div class="item">Dokumenty:</div><div class="div-scroll">';
      ret += getDokumenty(obj.dokument1);
      ret += "</div>";
    }
    if (obj.operatTechniczny1) {
      ret += '<div class="item">Operaty:</div><div class="div-scroll">';
      ret += getOperaty(obj.operatTechniczny1);
      ret += "</div>";
    }
    ret += '<div><span class="item">IIP: </span>';
    if (obj.idIIP) {
      ret += idIIPtoText(obj.idIIP);
    } else {
      ret += '<span class="error-inline">Brak IIP</span>';
    }
    ret += "</div>";
  } else {
    ret += '<div class="error">Brak zmiany o podanym gml id</div>';
  }
  ret += "</div>";
  return ret;
}
function pokazZmiane(id) {
  const wrapper = document.getElementById("main-wrapper");
  if (wrapper) {
    let html = '<div class="div-title"><span class="item">Zmiana: </span></div>';
    html += '<div class="grid-container">' + getZmiana(id) + "</div>";
    const div = document.createElement("div");
    div.innerHTML = html;
    wrapper.appendChild(div);
  }
}

// public/egib/dzialki-ewidencyjne.ts
var EGB_ZapisPowDzialki = {
  "1": "do m<sup>2</sup>",
  "2": "do ara"
};
function getOE(obj) {
  let ret = '<span class="span-title item">Obręb ewid.: </span>';
  ret += '<span class="cursor-pointer" id="' + "oe" /* iObrebEwidencyjny */ + obj._attributes.id + '" onclick="showEgbFeature(this.id)">';
  if (obj.idObrebu) {
    ret += obj.idObrebu.split(".")[1];
  } else {
    ret += '<span class="error-inline">Brak identyfikatora obrębu</span>';
  }
  ret += "</span>";
  if (obj.nazwaWlasna) {
    ret += "<span> (" + obj.nazwaWlasna + ")</span>";
  }
  return ret;
}
function getLokalizacja3(obj) {
  let ret = '<div class="div-title">';
  ret += '<span class="item">Identyfikator działki ewidencyjnej: </span>';
  if (obj.idDzialki) {
    ret += '<span class="bold">' + obj.idDzialki + "</span>";
  } else {
    ret += '<span class="error-inline">Brak identyfikatora działki</span>';
  }
  if (obj.lokalizacjaDzialki == null) {
    ret += '<span class="error-inline">&nbspBrak lokalizacji działki</span>';
  } else if (obj.lokalizacjaDzialki) {
    const objObr = egbFeatures.obrebyEwidencyjne.get(obj.lokalizacjaDzialki._attributes.href);
    if (objObr) {
      ret += getJE(objObr);
      ret += getOE(objObr);
      if (obj.idDzialki) {
        ret += '</span><span class="span-title item">Nr działki: </span><span>' + obj.idDzialki.split(".").pop() + "</span>";
      }
    } else {
      ret += '<span class="error-inline">&nbspBrak obrębu o podanym gml id</span>';
    }
  }
  ret += "</div>";
  return ret;
}
function getKlasouzytki(obj) {
  let ret = "<div>";
  if (obj.OFU) {
    ret += '<span class="cursor-default" title="' + EGB_OFU[obj.OFU] + '">' + obj.OFU + "</span>";
  } else {
    ret += '<span class="error-inline">Brak OFU.</span>';
  }
  if (obj.OZU) {
    if (obj.OZU.valueOf() !== obj.OFU?.valueOf()) {
      ret += "-" + '<span class="cursor-default" title="' + EGB_OZU[obj.OZU] + '">' + obj.OZU + "</span>";
    }
  }
  if (obj.OZK) {
    ret += obj.OZK;
  }
  if (obj.powierzchnia) {
    ret += " " + getArea(obj.powierzchnia);
  } else {
    ret += '<span class="error-inline">Brak powierzchni klasoużytków</span>';
  }
  ret += "</div>";
  return ret;
}
function getPoleKlasouzytki(obj) {
  let ret = "<div>";
  ret += '<div><span class="item">Pole ewid.: </span>';
  if (obj.poleEwidencyjne) {
    ret += getArea(obj.poleEwidencyjne);
  } else {
    ret += '<span class="error-inline">Brak wielkości pola ewidencyjnego</span>';
  }
  ret += "</div>";
  ret += '<div><span class="item">Dokładność: </span>';
  if (obj.dokladnoscReprezentacjiPola) {
    const dokladnoscReprezentacjiPola = EGB_ZapisPowDzialki[obj.dokladnoscReprezentacjiPola];
    if (dokladnoscReprezentacjiPola) {
      ret += dokladnoscReprezentacjiPola;
    } else {
      ret += '<span class="error-inline">Nieprawidłowa wartość</span>';
    }
  } else {
    ret += '<span class="error-inline">Brak dokładności pola ewidencyjnego</span>';
  }
  ret += "</div>";
  ret += '<div class="item">Klasoużytki:</div><div class="div-scroll">';
  if (obj.klasouzytek) {
    if (Array.isArray(obj.klasouzytek)) {
      obj.klasouzytek.forEach((key) => {
        if (key.EGB_Klasouzytek) {
          ret += getKlasouzytki(key.EGB_Klasouzytek);
        } else {
          ret += '<div class="error">Brak klasoużytków</div>';
        }
      });
    } else {
      if (obj.klasouzytek.EGB_Klasouzytek) {
        ret += getKlasouzytki(obj.klasouzytek.EGB_Klasouzytek);
      } else {
        ret += '<div class="error">Brak klasoużytków</div>';
      }
    }
  } else {
    ret += '<div class="error">Brak klasoużytków</div>';
  }
  ret += "</div>";
  ret += "</div>";
  return ret;
}
function getAdresInformacje(obj) {
  let ret = "<div>";
  if (obj.adresDzialki) {
    ret += '<div class="item">Adres działki:</div><div class="div-scroll">';
    ret += getAdresNieruchomosci(obj.adresDzialki);
    ret += "</div>";
  }
  if (obj.dodatkoweInformacje) {
    ret += '<div class="item">Dodatkowe informacje:</div><div>' + obj.dodatkoweInformacje + "</div>";
  }
  ret += "</div>";
  return ret;
}
function getPunktyGraniczne2(obj) {
  let ret = '<div><div class="item">Punkty graniczne:</div><div class="div-scroll">';
  if (obj.punktGranicyDzialki == null) {
    ret += '<div class="error-inline">Brak punktów granicznych</div>';
  } else if (obj.punktGranicyDzialki.length < 3) {
    ret += '<div class="error">Za mała liczba punktów granicznych</div>';
  } else {
    obj.punktGranicyDzialki.forEach((key) => {
      if (key) {
        ret += getIdPunktuGranicznego(key._attributes.href);
      }
    });
  }
  ret += "</div></div>";
  return ret;
}
function getJRG(obj) {
  let ret = '<div class="jrg-card"><span class="item">Jednostka rejestrowa gruntów: </span>';
  if (obj.JRG2 == null) {
    ret += '<span class="error-inline">Brak JRG</span>';
  } else if (obj.JRG2) {
    const objJe = egbFeatures.jednostkiRejestroweGruntow.get(obj.JRG2._attributes.href);
    if (objJe) {
      ret += '<span class="bold cursor-pointer" id="' + "rg" /* iJednostkaRejestrowaGruntow */ + objJe._attributes.id + '" onclick="showEgbFeature(this.id)">';
      if (objJe.idJednostkiRejestrowej) {
        ret += objJe.idJednostkiRejestrowej.split(".").pop();
      } else {
        ret += '<span class="error-inline">Brak identyfikatora JRG</span>';
      }
      ret += "</span>";
    } else {
      ret += '<span class="error-inline">Brak JRG o podanym gml id</span>';
    }
  }
  ret += "</div>";
  return ret;
}
function getIdBudynkuLokale(obj) {
  let ret = '<div class="building-card">';
  ret += '<div class="building-head"><span class="item">Budynek: </span>';
  ret += '<span class="bold cursor-pointer" id="' + "bu" /* iBudynek */ + obj._attributes.id + '" onclick="showEgbFeature(this.id)">';
  if (obj.idBudynku) {
    ret += obj.idBudynku.split(".").pop();
  } else {
    ret += '<span class="error">Brak identyfikatora budynku</span>';
  }
  ret += "</span></div>";
  const lokale = getLokaleIds(obj._attributes.id);
  if (lokale) {
    ret += '<div class="building-lokale"><div class="item">Lokale:</div>';
    ret += '<div class="building-lokale-list">' + lokale + "</div>";
    ret += "</div>";
  }
  ret += "</div>";
  return ret;
}
function getBudynki(id) {
  let tmp = "";
  for (const obj of egbFeatures.budynki.values()) {
    if (obj.dzialkaZabudowana) {
      if (Array.isArray(obj.dzialkaZabudowana)) {
        obj.dzialkaZabudowana.forEach((key) => {
          if (key._attributes.href === id) {
            tmp += getIdBudynkuLokale(obj);
          }
        });
      } else {
        if (obj.dzialkaZabudowana._attributes.href === id) {
          tmp += getIdBudynkuLokale(obj);
        }
      }
    }
  }
  if (!tmp) {
    return "";
  }
  let ret = '<div class="item-bold">Budynki i lokale:</div>';
  ret += '<div class="grid-container grid-container-buildings">' + tmp + "</div>";
  return ret;
}
function pokazDzialkeEwidencyjna(id) {
  const obj = egbFeatures.dzialkiEwidencyjne.get(id);
  if (obj) {
    showReportButton();
    if (obj.geometria) {
      showOnMapButton();
    }
    const wrapper = document.getElementById("main-wrapper");
    if (wrapper) {
      let html = getLokalizacja3(obj);
      html += '<div class="grid-container">';
      html += getOgolnyObiekt(obj);
      html += getDokWlasnosciKW(obj);
      html += getPoleKlasouzytki(obj);
      html += getAdresInformacje(obj);
      html += getPunktyGraniczne2(obj);
      html += getJRG(obj);
      html += "</div>";
      let div = document.createElement("div");
      div.innerHTML = html;
      wrapper.appendChild(div);
      div = document.createElement("div");
      div.innerHTML = '<div class="cursor-pointer item-italic">Pokaż udziały, budynki, lokale...</div>';
      div.addEventListener("click", function onClick(e) {
        let div = e.target;
        div.classList.remove("cursor-pointer");
        div.classList.remove("item-italic");
        let html = "";
        if (obj.JRG2) {
          html += getWlasnosciWladania(obj.JRG2._attributes.href);
          html += "<br>";
        }
        html += getBudynki(obj._attributes.id);
        div.innerHTML = html;
        this.removeEventListener("click", onClick);
      });
      wrapper.appendChild(div);
    }
  }
}

