function pokazUdzialWeWladaniu(id) {
  const obj = egbFeatures.udzialyWeWladaniu.get(id);
  if (obj) {
    const wrapper = document.getElementById("main-wrapper");
    if (wrapper) {
      let html = '<div class="div-title"><span class="item">Udział we władaniu: </span></div>';
      html += '<div class="grid-container">';
      html += getOgolnyObiekt(obj);
      html += getRodzaj3(obj);
      html += getWartosc2(obj);
      html += getPodmiotPrzedmiot2(obj);
      html += "</div>";
      let div = document.createElement("div");
      div.innerHTML = html;
      wrapper.appendChild(div);
    }
  }
}

